class Library {
  constructor() {
    this.books = {};
  }

  addBook(isbn, title, copies = 1) {
    if (typeof copies !== 'number' || copies <= 0) {
      throw new Error('Copies must be a positive integer');
    }
    if (!this.books[isbn]) {
      this.books[isbn] = { title, copies };
    } else {
      this.books[isbn].copies += copies;
    }
  }

  copies(isbn) {
    return this.books[isbn] ? this.books[isbn].copies : 0;
  }

  titles() {
    return Object.values(this.books).map(book => book.title).sort();
  }
}

module.exports = Library;

start.s3_matrix.js:
class Matrix {
  constructor(rows) {
    if (!Array.isArray(rows) || rows.length === 0) {
      throw new Error("No rows provided");
    }
    const numCols = rows[0].length;
    if (numCols === 0) {
      throw new Error("Empty rows");
    }
    for (const row of rows) {
      if (!Array.isArray(row) || row.length !== numCols) {
        throw new Error("Rows of different lengths");
      }
      for (const value of row) {
        if (typeof value !== 'number' || !isFinite(value)) {
          throw new Error("Non-finite number");
        }
      }
    }
    this.rows = rows;
  }

  shape() {
    return [this.rows.length, this.rows[0].length];
  }

  get(r, c) {
    if (r < 0 || r >= this.rows.length || c < 0 || c >= this.rows[0].length) {
      throw new Error("Index out of bounds");
    }
    return this.rows[r][c];
  }

  toArray() {
    return this.rows.map(row => [...row]);
  }
}

module.exports = Matrix;

