start.s1_library.js:
class Library {
  constructor() {
    this.books = {};
  }

  addBook(isbn, title, copies = 1) {
    if (typeof copies !== 'number' || copies <= 0) {
      throw new Error('Copies must be a positive integer');
    }
    if (!this.books[isbn]) {
      this.books[isbn] = { title, copies };
    } else {
      this.books[isbn].copies += copies;
    }
  }

  copies(isbn) {
    return this.books[isbn] ? this.books[isbn].copies : 0;
  }

  titles() {
    return Object.values(this.books).map(book => book.title).sort();
  }
}

module.exports = Library;

start.s3_matrix.js:
class Matrix {
  constructor(rows) {
    if (!Array.isArray(rows) || rows.length === 0) {
      throw new Error("No rows provided");
    }
    const numCols = rows[0].length;
    if (numCols === 0) {
      throw new Error("Empty rows");
    }
    for (const row of rows) {
      if (!Array.isArray(row) || row.length !== numCols) {
        throw new Error("Rows of different lengths");
      }
      for (const value of row) {
        if (typeof value !== 'number' || !isFinite(value)) {
          throw new Error("Non-finite number");
        }
      }
    }
    this.rows = rows;
  }

  shape() {
    return [this.rows.length, this.rows[0].length];
  }

  get(r, c) {
    if (r < 0 || r >= this.rows.length || c < 0 || c >= this.rows[0].length) {
      throw new Error("Index out of bounds");
    }
    return this.rows[r][c];
  }

  toArray() {
    return this.rows.map(row => [...row]);
  }
}

module.exports = Matrix;

start.s5_expr.js:
module.exports = {
  evaluate: function(expr) {
    // Remove spaces
    expr = expr.replace(/\s+/g, '');

    // Simple evaluation
    const tokens = expr.split(/(\+|\-|\*|\/)/);
    let result = parseFloat(tokens[0]);

    for (let i = 1; i < tokens.length; i += 2) {
      const operator = tokens[i];
      const nextValue = parseFloat(tokens[i + 1]);

      switch (operator) {
        case '+':
          result += nextValue;
          break;
        case '-':
          result -= nextValue;
          break;
        case '*':
          result *= nextValue;
          break;
        case '/':
          if (nextValue === 0) {
            throw new Error('Division by zero');
          }
          result /= nextValue;
          break;
        default:
          throw new Error('Invalid operator');
      }
    }

    return result;
  }
};

start.test_s1_library.js:
const Library = require('./s1_library.js');
const assert = require('assert');

describe('Library', function() {
  let library;

  beforeEach(function() {
    library = new Library();
  });

  describe('addBook', function() {
    it('should add a new book', function() {
      library.addBook('12345', 'Book One');
      assert.strictEqual(library.copies('12345'), 1);
    });

    it('should add copies to an existing book', function() {
      library.addBook('12345', 'Book One');
      library.addBook('12345', 'Book One', 2);
      assert.strictEqual(library.copies('12345'), 3);
    });

    it('should throw an error for non-positive copies', function() {
      assert.throws(() => library.addBook('12345', 'Book One', -1), Error);
      assert.throws(() => library.addBook('12345', 'Book One', 0), Error);
      assert.throws(() => library.addBook('12345', 'Book One', 'a'), Error);
    });
  });

  describe('copies', function() {
    it('should return the number of copies for a known isbn', function() {
      library.addBook('12345', 'Book One', 3);
      assert.strictEqual(library.copies('12345'), 3);
    });

    it('should return 0 for an unknown isbn', function() {
      assert.strictEqual(library.copies('67890'), 0);
    });
  });

  describe('titles', function() {
    it('should return an empty array if no books are added', function() {
      assert.deepStrictEqual(library.titles(), []);
    });

    it('should return an array of titles sorted alphabetically', function() {
      library.addBook('12345', 'Book One');
      library.addBook('67890', 'Book Two');
      library.addBook('54321', 'Book Three');
      assert.deepStrictEqual(library.titles(), ['Book One', 'Book Three', 'Book Two']);
    });
  });
});

start.test_s3_matrix.js:
const assert = require('assert');
const Matrix = require('./s3_matrix.js');

// Test constructor
assert.throws(() => new Matrix(), Error, "No rows provided");
assert.throws(() => new Matrix([]), Error, "No rows provided");
assert.throws(() => new Matrix([[]]), Error, "Empty rows");
assert.throws(() => new Matrix([[1], [2, 3]]), Error, "Rows of different lengths");
assert.throws(() => new Matrix([[1, 'a'], [2, 3]]), Error, "Non-finite number");

// Test shape
const matrix = new Matrix([[1, 2], [3, 4]]);
assert.deepStrictEqual(matrix.shape(), [2, 2]);

// Test get
assert.strictEqual(matrix.get(0, 0), 1);
assert.strictEqual(matrix.get(1, 1), 4);
assert.throws(() => matrix.get(-1, 0), Error, "Index out of bounds");
assert.throws(() => matrix.get(0, 2), Error, "Index out of bounds");

// Test toArray
const matrixCopy = matrix.toArray();
assert.deepStrictEqual(matrixCopy, [[1, 2], [3, 4]]);
matrixCopy[0][0] = 10;
assert.notDeepStrictEqual(matrixCopy, matrix.rows);

console.log("All tests passed");

